export function getFeaturedHomeProducts() {
  const byId = new Map(CATALOG.map((product) => [product.id, product]));
  return FEATURED_HOME_PRODUCT_IDS.map((id) => byId.get(id)).filter(Boolean);
}

export function getProductsByCategory(categorySlug = 'all') {
  if (!categorySlug || categorySlug === 'all') return CATALOG;
  return CATALOG.filter((product) => product.category === categorySlug);
}

export function getCategoryBySlug(slug) {
  return PRODUCT_CATEGORIES.find((category) => category.slug === slug);
}

export function getProductSpecs(product) {
  const brand = product.brand || 'Five Group';
  const category = product.category || '';
  const defaults = {
    brand,
    origin: 'International',
    format: product.notes,
    caseFormat: 'As per catalog sheet',
    storage: 'Ambient storage unless stated on pack',
    shelfLife: 'See packaging',
    certificates: 'Halal · ISO compliant supply chain',
  };
  const byCategory = {
    beverages: { origin: 'Thailand', format: '320ml bottle', caseFormat: '24 bottles per case', storage: 'Ambient, chilled after opening', shelfLife: '24 months', certificates: 'Halal, GMP, HACCP' },
    'chocalates-confectionery': { origin: 'Poland', format: 'Retail & bulk packs', caseFormat: '10–14 units per carton', storage: 'Cool & dry (16–20°C)', shelfLife: '12 months', certificates: 'Halal, ISO 22000' },
    'non-food': { origin: 'GCC / International', format: 'Household pack sizes', caseFormat: 'Multi-pack promo cartons', storage: 'Dry storage', shelfLife: '36 months', certificates: 'Quality assured imports' },
    'tinned-food': { origin: 'International', format: 'Tinned retail packs', caseFormat: '12–24 tins per case', storage: 'Cool, dry place', shelfLife: '24–36 months', certificates: 'Halal where applicable' },
    jam: { origin: 'International', format: 'Glass jar', caseFormat: '12 jars per case', storage: 'Ambient', shelfLife: '18 months', certificates: 'Halal' },
    pickles: { origin: 'International', format: 'Glass jar', caseFormat: '12 jars per case', storage: 'Ambient', shelfLife: '24 months', certificates: 'Halal' },
    rice: { origin: 'India / Pakistan', format: 'PP bag', caseFormat: '10kg / 20kg sacks', storage: 'Dry, ventilated', shelfLife: '24 months', certificates: 'Food-grade handling' },
  };
  return { ...defaults, ...(byCategory[category] || {}) };
}
